//! Differential test: stateful replay of the original `Position.sol`.
//!
//! The trace is generated by `diff-tests/` (Foundry) from the windv3swap Solidity code:
//! `cd diff-tests && forge test --match-test testGeneratePosition`
//!
//! Each line is one `Position.update` call on a `PositionHarness`, with the state after it:
//! `update|key|liquidityDelta|fg0|fg1|staked|ok|liquidity|fg0Last|fg1Last|owed0|owed1`, or
//! `update|key|liquidityDelta|fg0|fg1|staked|err` when the Solidity reverted.

use std::fs;
use std::path::PathBuf;

use windswap_engine::pool::position::{PositionInfo, PositionKey, Positions};
use windswap_engine::{MathError, U256};

/// Key index `k` maps to owner `0xA000 + k / 3` and one of three tick ranges.
fn key(k: usize) -> PositionKey {
    let mut owner = [0u8; 32];
    // The 20-byte address 0xA000 + (k / 3) is left-padded to 32 bytes.
    owner[30] = 0xA0;
    owner[31] = (k / 3) as u8;
    let (tick_lower, tick_upper) = match k % 3 {
        0 => (-120, 120),
        1 => (-60, 60),
        _ => (0, 600),
    };
    PositionKey {
        owner,
        tick_lower,
        tick_upper,
    }
}

fn u(s: &str) -> U256 {
    s.parse().unwrap()
}

#[derive(Debug)]
struct Step {
    key: usize,
    delta: i128,
    fg0: U256,
    fg1: U256,
    staked: bool,
    /// State after the update, or `None` if Solidity reverted.
    expected: Option<PositionInfo>,
}

fn steps() -> Vec<Step> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../diff-tests/vectors")
        .join("position.txt");
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    text.lines()
        .filter(|l| !l.is_empty())
        .enumerate()
        .map(|(n, line)| {
            let p: Vec<&str> = line.split('|').collect();
            assert_eq!(p[0], "update", "line {n}: {line}");
            assert!(p.len() >= 7, "line {n}: {line}");
            let expected = match p[6] {
                "ok" => {
                    assert_eq!(p.len(), 12, "line {n}: {line}");
                    Some(PositionInfo {
                        liquidity: p[7].parse().unwrap(),
                        fee_growth_inside0_last_x128: u(p[8]),
                        fee_growth_inside1_last_x128: u(p[9]),
                        tokens_owed0: p[10].parse().unwrap(),
                        tokens_owed1: p[11].parse().unwrap(),
                    })
                }
                "err" => {
                    assert_eq!(p.len(), 7, "line {n}: {line}");
                    None
                }
                other => panic!("line {n}: bad status {other}"),
            };
            Step {
                key: p[1].parse().unwrap(),
                delta: p[2].parse().unwrap(),
                fg0: u(p[3]),
                fg1: u(p[4]),
                staked: p[5] == "1",
                expected,
            }
        })
        .collect()
}

#[derive(Debug, Default)]
struct Coverage {
    ok: usize,
    err: usize,
    staked_ok: usize,
    unstaked_ok: usize,
    no_position_liquidity: usize,
    liquidity_sub: usize,
    liquidity_add: usize,
    /// Unstaked updates where `feeGrowthInside - last` wrapped below zero.
    fee_growth_wraps: usize,
    /// Updates where `tokensOwed` wrapped around `uint128`.
    tokens_owed_wraps: usize,
}

#[test]
fn position_replay_matches_solidity() {
    let steps = steps();
    assert!(!steps.is_empty(), "no vectors in position.txt");

    let mut positions = Positions::new();
    let mut cov = Coverage::default();

    for (n, step) in steps.iter().enumerate() {
        let pos = positions.entry(key(step.key)).or_default();
        let before = pos.clone();
        let result = pos.update(step.delta, step.fg0, step.fg1, step.staked);

        match (&step.expected, result) {
            (Some(exp), Ok(())) => {
                assert_eq!(*pos, *exp, "step {n}: {step:?}");
                cov.ok += 1;
                if step.staked {
                    cov.staked_ok += 1;
                } else {
                    cov.unstaked_ok += 1;
                    if step.fg0 < before.fee_growth_inside0_last_x128
                        || step.fg1 < before.fee_growth_inside1_last_x128
                    {
                        cov.fee_growth_wraps += 1;
                    }
                }
                if pos.tokens_owed0 < before.tokens_owed0 || pos.tokens_owed1 < before.tokens_owed1
                {
                    cov.tokens_owed_wraps += 1;
                }
            }
            (None, Err(e)) => {
                // A failed update must not change the position.
                assert_eq!(
                    *pos, before,
                    "step {n}: failed update wrote state: {step:?}"
                );
                cov.err += 1;
                match e {
                    MathError::NoPositionLiquidity => cov.no_position_liquidity += 1,
                    MathError::LiquiditySub => cov.liquidity_sub += 1,
                    MathError::LiquidityAdd => cov.liquidity_add += 1,
                    other => panic!("step {n}: unexpected error {other:?}: {step:?}"),
                }
            }
            (Some(exp), Err(e)) => {
                panic!("step {n}: Solidity returned {exp:?}, Rust errored {e:?}: {step:?}")
            }
            (None, Ok(())) => {
                panic!(
                    "step {n}: Solidity reverted, Rust returned {:?}: {step:?}",
                    *pos
                )
            }
        }
    }

    // The trace must actually exercise every interesting path.
    assert!(cov.ok > 0 && cov.err > 0, "{cov:?}");
    assert!(cov.staked_ok > 0 && cov.unstaked_ok > 0, "{cov:?}");
    assert!(cov.no_position_liquidity > 0, "{cov:?}");
    assert!(cov.liquidity_sub > 0 && cov.liquidity_add > 0, "{cov:?}");
    assert!(cov.fee_growth_wraps > 0, "{cov:?}");
    assert!(cov.tokens_owed_wraps > 0, "{cov:?}");
}
